messages.content:
Tool response:
Tool: record_exam_result
Description: Record an exam result for a candidate.
Parameters:
    {
      "type": "object",
      "properties": {
        "candidate_id": {
          "type": "string",
          "title": "Candidate Id",
          "description": "The unique identifier of the candidate"
        },
        "exam_id": {
          "type": "integer",
          "title": "Exam Id",
          "description": "The ID of the exam taken"
        },
        "test_center_id": {
          "type": "integer",
          "title": "Test Center Id",
          "description": "The ID of the test center where the exam was taken"
        },
        "score": {
          "type": "number",
          "maximum": 100.0,
          "minimum": 0.0,
          "title": "Score",
          "description": "The score achieved by the candidate (between 0 and 100)"
        },
        "result": {
          "type": "string",
          "pattern": "^(pass|fail)$",
          "title": "Result",
          "description": "The result of the exam ('pass' or 'fail')"
        },
        "exam_date": {
          "type": "string",
          "title": "Exam Date",
          "description": "The date when the exam was taken (YYYY-MM-DD)"
        },
        "created_by": {
          "type": "integer",
          "title": "Created By",
          "description": "The ID of the user who recorded the result"
        }
      },
      "required": [
        "candidate_id",
        "exam_id",
        "test_center_id",
        "score",
        "result",
        "exam_date",
        "created_by"
      ]
    }
